+        state.handle_mouse(up, resized);
+        state.handle_mouse(up, area);
+        assert!(
+            state.reasoning_expanded.is_empty(),
+            "resize roundtrip does not revive the press"
+        );
+        state.handle_mouse(down, area);
+        state.handle_mouse(up, area);
