+        if rows.iter().any(|row| row.contains("+ Thought: Click plan"))
+            && !rows.iter().any(|row| row.contains(REASONING_CLICK_BODY))
+        {
+            break;
+        }
+        assert!(
+            started.elapsed() < DEADLINE,
+            "reasoning did not collapse: {rows:?}"
+        );
+        std::thread::sleep(POLL);
+    }
